cat > workbench.css <<'EOF'
:root {
  color-scheme: light;
  --ink: #21272f;
  --muted: #565c65;
  --paper: #fffefa;
  --canvas: #f5f3ee;
  --line: #deded6;
  --navy: #182746;
  --blue: #274b98;
  --pale-blue: #eaf0fb;
  --serif: Georgia, \"Times New Roman\", serif;
  --sans: system-ui, -apple-system, \"Segoe UI\", sans-serif;
  --mono: ui-monospace, \"SFMono-Regular\", Consolas, monospace;
  font: 16px/1.5 var(--sans);
  color: var(--ink);
  background: var(--canvas);
}
*, *::before, *::after { box-sizing: border-box; }
body { margin: 0; }
[hidden] { display: none "'!important; }
h1, h2, p { margin: 0; }
button, input, textarea { font: inherit; }
button { cursor: pointer; }
button:disabled { opacity: .38; cursor: default; }
:focus-visible { outline: 3px solid #3862c3; outline-offset: 3px; }
.symbol-library { position: absolute; width: 0; height: 0; overflow: hidden; }
.icon { display: inline-block; width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.65; stroke-linecap: round; stroke-linejoin: round; }
.skip { position: absolute; top: 8px; left: 8px; z-index: 5; padding: 10px 14px; color: var(--navy); background: white; transform: translateY(-160%); }
