.wrap { width: min(100% - 96px, 1520px); margin-inline: auto; }
.masthead { background: var(--navy); color: #fff; }
.masthead-inner { display: flex; justify-content: space-between; align-items: center; min-height: 88px; gap: 20px; padding-block: 14px; }
.brand, .print-actions { display: flex; align-items: center; gap: 12px; }
.brand-mark { width: 42px; height: 42px; border: 1px solid #8292b6; display: grid; place-items: center; color: #e6edff; }
.brand-mark .icon { width: 24px; height: 24px; stroke-width: 1.3; }
.brand-kicker { color: #c5d0e9; font: 600 .67rem/1.2 var(--mono); text-transform: uppercase; letter-spacing: .12em; margin-bottom: 3px; }
.brand-name { font: 1.27rem/1.16 var(--serif); }
.button { min-height: 44px; padding: 8px 13px; display: inline-flex; justify-content: center; align-items: center; gap: 8px; border: 1px solid transparent; border-radius: 4px; font-weight: 650; font-size: .85rem; }
.secondary { background: transparent; color: #f2f5fd; border-color: #7284a7; }
.secondary:hover:not(:disabled) { background: #293b61; }
.primary { background: #f4f6ff; color: var(--navy); border-color: #f4f6ff; }
.primary:hover:not(:disabled) { background: #dce6ff; border-color: #dce6ff; }
.masthead :focus-visible { outline-color: #d4e0ff; }
.intro { display: flex; align-items: end; justify-content: space-between; gap: 16px; padding-block: 39px 29px; }
h1 { font: 400 clamp(2.5rem, 4.1vw, 4rem)/1.03 var(--serif); letter-spacing: -.055em; color: var(--navy); }
.intro p { margin-top: 9px; color: var(--muted); }
.save-state { display: flex; align-items: center; gap: 8px; font-size: .81rem; color: #45524e; padding-block: 4px; }
.save-dot { width: 7px; height: 7px; border-radius: 100%; background: #43745c; flex: none; }
.save-state.unsaved { color: #853926; }
.unsaved .save-dot { background: #a9482e; }
.workbench { display: grid; grid-template-columns: minmax(205px, .76fr) minmax(325px, 1.2fr) minmax(360px, 1.45fr); gap: 16px; align-items: stretch; }
.panel { border: 1px solid var(--line); border-radius: 5px; min-width: 0; background: var(--paper); display: flex; flex-direction: column; }
.panel-heading { display: flex; justify-content: space-between; align-items: start; gap: 8px; padding: 19px 20px 16px; border-bottom: 1px solid var(--line); }
h2 { font: 400 1.5rem/1.17 var(--serif); color: var(--navy); letter-spacing: -.025em; }
.panel-heading p { color: var(--muted); font-size: .81rem; margin-top: 4px; }
.counter, .format-tag { color: var(--blue); font: 600 .73rem/1.3 var(--mono); background: var(--pale-blue); border-radius: 3px; padding: 5px 7px; white-space: nowrap; }
.work-list { list-style: none; padding: 0; margin: 0; }
.work-list li { border-bottom: 1px solid var(--line); }
.work-button { width: 100%; min-height: 67px; border: 0; border-left: 3px solid transparent; padding: 12px 12px 12px 15px; background: transparent; text-align: left; color: var(--ink); display: grid; grid-template-columns: 2ch minmax(0, 1fr) auto; gap: 11px; align-items: start; }
.work-button:hover { background: #f3f5fa; }
.work-button[aria-current="true"] { background: var(--pale-blue); border-left-color: var(--blue); }
.work-button:focus-visible { outline-offset: -4px; }
.work-number { color: var(--blue); font: 600 .72rem/1.6 var(--mono); margin-top: 2px; }
.work-name { display: block; font-size: .87rem; line-height: 1.35; font-weight: 700; overflow-wrap: anywhere; }
.work-artist { display: block; font-size: .77rem; color: var(--muted); margin-top: 3px; overflow-wrap: anywhere; }
.work-name, .work-artist { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden; }
.work-flag { width: 15px; height: 15px; color: #88470f; margin-top: 2px; }
.add-area { padding: 14px 16px; }
.add-button { width: 100%; border: 1px dashed #a3aec6; color: var(--blue); background: transparent; }
.add-button:hover { background: var(--pale-blue); }
.order-controls { margin-top: auto; min-height: 68px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 6px; padding: 10px 15px; border-top: 1px solid var(--line); color: var(--muted); font-size: .77rem; }
.arrow-group { display: flex; gap: 6px; }
.icon-button { width: 44px; height: 44px; display: inline-grid; place-items: center; background: var(--paper); border: 1px solid var(--line); border-radius: 4px; color: var(--navy); padding: 0; }
.icon-button:hover:not(:disabled) { background: var(--pale-blue); border-color: #b2c1e1; }
#artwork-form { display: grid; gap: 13px; padding: 16px 20px 10px; }
.field { display: grid; align-content: start; gap: 4px; min-width: 0; }
.field-pair { display: grid; grid-template-columns: minmax(0, 1fr) minmax(72px, .35fr); gap: 10px; }
label { font-size: .81rem; font-weight: 650; }
label span { color: var(--muted); font-weight: 400; margin-left: 4px; }
input, textarea { width: 100%; min-height: 44px; padding: 8px 10px; border: 1px solid #c8cad0; border-radius: 4px; background: #fff; color: var(--ink); font-size: 1rem; }
input::placeholder, textarea::placeholder { color: #686e77; }
textarea { resize: vertical; min-height: 63px; }
small { color: var(--muted); font-size: .75rem; }
.edit-footer { border-top: 1px solid var(--line); }
.remove-button { display: inline-flex; align-items: center; gap: 7px; min-height: 44px; border: 0; background: none; color: #863624; padding: 4px 4px 4px 0; font-size: .8rem; }
.remove-button:hover { text-decoration: underline; }
.remove-button .icon { width: 15px; height: 15px; }
.empty-list, .empty-editor { color: var(--muted); padding: 18px; font-size: .875rem; }
.proof-stage { flex: 1; min-height: 294px; padding: 33px 39px 40px 21px; display: grid; place-items: center; background-color: #eceeea; background-image: radial-gradient(#aeb8b7 0.7px, transparent 0.7px); background-size: 12px 12px; }
.proof-figure { position: relative; visibility: hidden; }
.proof-size { position: relative; box-shadow: 0 3px 14px #24324a26; }
.proof-size .label-card { position: absolute; inset: 0 auto auto 0; transform-origin: top left; }
.proof-width, .proof-height { color: #485762; position: absolute; display: grid; place-items: center; font: 600 .69rem/1 var(--mono); white-space: nowrap; }
.proof-width { inset: auto 0 100%; height: 23px; margin-bottom: 1px; }
.proof-height { inset: 0 auto 0 100%; width: 22px; margin-left: 4px; }
.proof-width::before, .proof-height::before { content: ""; position: absolute; border: solid #758690; }
.proof-width::before { inset: 9px 0 7px; border-width: 0 1px 1px; }
.proof-height::before { inset: 0 10px 0 5px; border-width: 1px 1px 1px 0; }
.proof-width span, .proof-height span { position: relative; background: #eceeea; padding: 3px 5px; }
.proof-height span { writing-mode: vertical-rl; padding: 5px 3px; }
#empty-proof { text-align: center; background: var(--paper); padding: 8px 12px; font-size: .85rem; }
.preview-report { min-height: 64px; display: flex; gap: 9px; align-items: flex-start; padding: 12px 16px; border-top: 1px solid var(--line); color: #335744; background: #f1f6f0; font-size: .82rem; }
.preview-report .icon { margin-top: 2px; }
.preview-report p { color: var(--muted); font-size: .75rem; }
.preview-report.warning { color: #763a14; background: #fff0dc; }
.preview-report.warning p { color: #663e24; }
.proof-nav { display: flex; align-items: center; justify-content: center; gap: 13px; padding: 10px; border-top: 1px solid var(--line); color: var(--muted); font: 600 .74rem/1.3 var(--mono); }
.workspace-footer { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 18px; margin-top: 17px; padding-block: 10px 22px; border-top: 1px solid #c9cbd1; color: var(--muted); font-size: .76rem; }
.workspace-footer span:first-child { font-family: var(--mono); color: var(--navy); }
.divider { padding-inline: 3px; }

dialog { color: var(--ink); background: var(--paper); border: 1px solid var(--line); border-radius: 6px; padding: 20px; width: min(490px, calc(100% - 32px)); max-height: calc(100% - 32px); box-shadow: 0 15px 50px #14203944; }
dialog::backdrop { background: #142039aa; }
.dialog-heading { display: flex; gap: 12px; align-items: center; justify-content: space-between; margin-bottom: 10px; }
#dialog-content { overflow-wrap: anywhere; }
#dialog-content p + p { margin-top: 10px; }
.dialog-actions { display: flex; gap: 8px; justify-content: end; margin-top: 20px; }
.neutral { border-color: var(--line); background: var(--paper); color: var(--navy); }
.neutral:hover { background: var(--pale-blue); }
.solid { color: white; background: var(--blue); }
.solid:hover { background: var(--navy); }
.solid.danger { background: #863624; }
.issue-link { text-decoration: underline; color: var(--blue); border: 0; text-align: start; background: transparent; padding: 5px 0; min-height: 44px; overflow-wrap: anywhere; max-width: 100%; }

.label-card {
  width: 90mm;
  height: 55mm;
  padding: 6mm;
  color: #16171b;
  background: white;
  overflow: hidden;
  font: 10pt/1.25 Arial, sans-serif;
}
