  .check-box { display: inline-block; width: 3.5mm; height: 3.5mm; flex: none; border: .25mm solid black; margin-right: 2mm; }
  .check-number { flex: 0 0 5.5mm; font: 8pt var(--mono); }
  .check-credit { font-style: italic; }
  .print-notice { padding: 4mm; overflow-wrap: anywhere; }
  .print-notice p { margin-top: 3mm; }
}
EOF'

