const storageKey = \"gallery-label-workbench.v1\";
const fields = [\"title\", \"artist\", \"year\", \"medium\", \"dimensions\", \"credit\"];
const samples = [
  { id: \"tide\", title: \"Tide Marks\", artist: \"Mara Fenwick\", year: \"2024\", medium: \"graphite on paper\", dimensions: \"21 × 30 cm\", credit: \"\" },
  { id: \"window\", title: \"Window Light After Rain\", artist: \"Ines Vale\", year: \"2025\", medium: \"oil on panel\", dimensions: \"40 × 50 cm\", credit: \"\" },
  { id: \"fold\", title: \"Fold Study IV\", artist: \"Rowan Bellmere\", year: \"2023\", medium: \"folded linen\", dimensions: \"18 × 18 × 6 cm\", credit: \"\" },
];

const byId = (id) => document.getElementById(id);

function node(tag, className, value) {
  const element = document.createElement(tag);
  if (className) element.className = className;
  if (value "'!== undefined) element.textContent = value;
  return element;
}

function icon(name) {
  const namespace = "http://www.w3.org/2000/svg";
  const svg = document.createElementNS(namespace, "svg");
  const use = document.createElementNS(namespace, "use");
  svg.setAttribute("class", "icon");
  svg.setAttribute("aria-hidden", "true");
  use.setAttribute("href", "#i-" + name);
  svg.append(use);
  return svg;
}

function loadWorkspace() {
  try {
    const raw = localStorage.getItem(storageKey);
    if (raw === null) return { works: samples, selectedId: samples[0].id };
    const saved = JSON.parse(raw);
    const ids = new Set();
    if (!Array.isArray(saved.works)) throw new Error("Invalid work list");
    for (const work of saved.works) {
      if (typeof work.id !== "string" || ids.has(work.id) ||
          fields.some((field) => typeof work[field] !== "string")) {
        throw new Error("Invalid artwork");
      }
      ids.add(work.id);
    }
    return { works: saved.works, selectedId: saved.selectedId };
  } catch {
    return { works: samples, selectedId: samples[0].id, loadError: true };
  }
}

let { works, selectedId, loadError } = loadWorkspace();
if (!works.some((work) => work.id === selectedId)) selectedId = works[0]?.id;
const artworkForm = byId("artwork-form");
const inputs = Object.fromEntries(fields.map((field) => [field, byId(field)]));
const workList = byId("work-list");
const proofSize = byId("proof-size");
const proofStage = byId("proof-stage");
const proofFigure = byId("proof-figure");
const report = byId("preview-report");
const measure = byId("measure-label");
const printOutput = byId("print-output");
const dialog = byId("action-dialog");
const issueMap = new Map();
let dialogAction;
let printMode;
let nextId = Date.now();
let previousReport;

function saveWorkspace() {
  const status = byId("save-status");
  try {
    localStorage.setItem(storageKey, JSON.stringify({ works, selectedId }));
    status.textContent = "Saved on this device";
    status.parentElement.classList.remove("unsaved");
  } catch {
    status.textContent = "Local saving unavailable. Keep this tab open.";
    status.parentElement.classList.add("unsaved");
  }
}

function titleOf(work) {
  return work.title.trim() ? work.title : "Untitled artwork";
}

function positionOf(id = selectedId) {
  return works.findIndex((work) => work.id === id);
}

function metadata(work) {
  return [work.year, work.medium].filter((value) => value.trim()).join(" · ");
}

function labelFor(work) {
  const card = node("div", "label-card");
  const content = node("div", "label-content");
  content.append(node("div", "label-field label-title", titleOf(work)));
  if (work.artist.trim()) content.append(node("div", "label-field label-artist", work.artist));

  const meta = node("div", "label-meta");
  const description = metadata(work);
  if (description) meta.append(node("div", "label-field", description));
  if (work.dimensions.trim()) meta.append(node("div", "label-field", work.dimensions));
  if (meta.childElementCount) content.append(meta);
  if (work.credit.trim()) content.append(node("div", "label-field label-credit", work.credit));
  card.append(content);
  return card;
}

function checkLabel(work, card) {
  measure.replaceChildren(card);
  const content = card.firstElementChild;
  const contentBox = content.getBoundingClientRect();
  const lastField = content.lastElementChild.getBoundingClientRect();
  const overflow = lastField.bottom > contentBox.bottom + 0.01 ||
    content.scrollWidth > content.clientWidth;
  measure.replaceChildren();
  const missing = fields.slice(0, -1).some((field) => !work[field].trim());
  const result = { overflow, missing };
  issueMap.set(work.id, result);
  return result;
}

function layoutProof() {
  const card = proofSize.firstElementChild;
  if (!card) return;
  const style = getComputedStyle(proofStage);
  const available = proofStage.clientWidth - parseFloat(style.paddingLeft) - parseFloat(style.paddingRight);
  if (available <= 0) return;
  const width = card.offsetWidth;
  const height = card.offsetHeight;
  const scale = Math.min(1, available / width);
  proofSize.style.width = width * scale + "px";
  proofSize.style.height = height * scale + "px";
  card.style.transform = "scale(" + scale + ")";
  proofFigure.style.visibility = "visible";
}

function updatePreview(work) {
  proofFigure.hidden = !work;
  byId("empty-proof").hidden = Boolean(work);
  report.hidden = !work;
  if (!work) {
    proofSize.replaceChildren();
    return;
  }
  const card = labelFor(work);
  const { overflow, missing } = checkLabel(work, card);
  card.classList.toggle("overflows", overflow);
  proofSize.replaceChildren(card);
  layoutProof();
  const state = overflow ? "overflow" : missing ? "missing" : "ready";
  if (state === previousReport) return;
  previousReport = state;
  const messages = {
    overflow: ["Text exceeds the label area", "A shorter title or credit may help. Your full text is saved in the fields."],
    missing: ["Details missing", "Fill in the five required fields to print this label."],
    ready: ["Fits at trim size", "Text stays within the 6 mm inset."],
  };
  const [heading, detail] = messages[state];
  const body = node("div");
  body.append(node("strong", "", heading), node("p", "", detail));
  report.classList.toggle("warning", state !== "ready");
  report.replaceChildren(icon(state === "ready" ? "check" : "warning"), body);
}

function updateListEntry(button, work) {
  const { overflow, missing } = issueMap.get(work.id);
  button.querySelector(".work-name").textContent = titleOf(work);
  button.querySelector(".work-artist").textContent = work.artist.trim() ? work.artist : "Artist pending";
  const flag = button.querySelector(".work-flag");
  flag.toggleAttribute("hidden", !overflow && !missing);
  const status = overflow ? "Text overflow" : missing ? "Details missing" : "";
  button.querySelector(".work-status").textContent = status;
}

function renderList() {
  const rows = works.map((work, index) => {
    const row = node("li");
    const button = node("button", "work-button");
    button.type = "button";
    button.dataset.id = work.id;
    button.setAttribute("aria-current", String(work.id === selectedId));
    const lines = node("span");
    lines.append(node("span", "work-name"), node("span", "work-artist"), node("span", "visually-hidden work-status"));
    const flag = icon("warning");
    flag.classList.add("work-flag");
    button.append(node("span", "work-number", String(index + 1).padStart(2, "0")), lines, flag);
    updateListEntry(button, work);
    row.append(button);
    return row;
  });
  workList.replaceChildren(...rows);
}

function renderWorkspace() {
  const index = positionOf();
  const work = works[index];
  artworkForm.hidden = !work;
  byId("empty-list").hidden = Boolean(work);
  byId("empty-editor").hidden = Boolean(work);
  byId("order-controls").hidden = !work;
  byId("work-count").textContent = String(works.length);
  byId("edit-position").textContent = work ? "Work " + (index + 1) + " of " + works.length : "Select a work";
  byId("proof-position").textContent = work ? (index + 1) + " / " + works.length : "No labels";
  byId("print-labels").disabled = !work;
  byId("print-checklist").disabled = !work;
  byId("move-up").disabled = byId("previous-work").disabled = index <= 0;
  byId("move-down").disabled = byId("next-work").disabled = !work || index >= works.length - 1;
  if (work) {
    for (const field of fields) inputs[field].value = work[field];
  }
  updatePreview(work);
  renderList();
}

function selectWork(id) {
  if (!works.some((work) => work.id === id)) return;
  selectedId = id;
  saveWorkspace();
  renderWorkspace();
}

function moveWork(offset) {
  const index = positionOf();
  const target = index + offset;
  if (index < 0 || target < 0 || target >= works.length) return;
  [works[index], works[target]] = [works[target], works[index]];
  saveWorkspace();
  renderWorkspace();
  const control = byId(offset < 0 ? "move-up" : "move-down");
  if (control.disabled) byId(offset < 0 ? "move-down" : "move-up").focus();
}

function addWork() {
  let id;
  do {
    id = "work-" + nextId++;
  } while (works.some((work) => work.id === id));
  const work = { id };
  for (const field of fields) work[field] = "";
  works.push(work);
  selectWork(work.id);
  inputs.title.focus();
}

function openDialog(title, body, confirmText, action, destructive = false) {
  byId("dialog-title").textContent = title;
  byId("dialog-content").replaceChildren(...body);
  byId("confirm-dialog").textContent = confirmText || "";
  byId("confirm-dialog").hidden = !confirmText;
  byId("confirm-dialog").classList.toggle("danger", destructive);
  byId("cancel-dialog").textContent = confirmText ? "Cancel" : "Close";
  dialogAction = action;
  dialog.returnValue = "";
  dialog.showModal();
  byId(destructive || !confirmText ? "cancel-dialog" : "confirm-dialog").focus();
}

function removeWork() {
  const work = works[positionOf()];
  if (!work) return;
  openDialog("Remove artwork?", [node("p", "", "“" + titleOf(work) + "” will be removed from the hanging order.")], "Remove artwork", () => {
    const index = positionOf(work.id);
    works.splice(index, 1);
    issueMap.delete(work.id);
    selectedId = works[Math.min(index, works.length - 1)]?.id;
    saveWorkspace();
    renderWorkspace();
    byId(selectedId ? "remove-work" : "add-work").focus();
  }, true);
}

function labelIssues() {
  return works.filter((work) => {
    const { overflow, missing } = issueMap.get(work.id);
    return overflow || missing;
  });
}

function confirmPrint(mode) {
  if (mode === "labels") {
    const issues = labelIssues();
    if (issues.length) {
      const list = node("ul");
      for (const work of issues) {
        const item = node("li");
        const { overflow, missing } = issueMap.get(work.id);
        const reason = overflow && missing ? "Text overflow and details missing" :
          overflow ? "Text overflow" : "Details missing";
        const button = node("button", "issue-link", (positionOf(work.id) + 1) + ". " + titleOf(work) + " — " + reason);
        button.type = "button";
        button.addEventListener("click", () => {
          dialog.close();
          selectWork(work.id);
          inputs.title.focus();
        });
        item.append(button);
        list.append(item);
      }
      openDialog("Review labels before printing", [
        node("p", "", "Select an artwork below to resolve its label warning."),
        list,
      ]);
      return;
    }
  }
  const summary = mode === "labels"
    ? works.length + (works.length === 1 ? " label on " : " labels across ") + Math.ceil(works.length / 8) +
      (works.length <= 8 ? " sheet. Cut along the corner marks." : " sheets. Cut along the corner marks.")
    : "The checklist follows your hanging order, with a checkbox beside each work.";
  openDialog(mode === "labels" ? "Print labels" : "Print checklist", [
    node("p", "", summary),
    node("p", "", "Choose A4 portrait and Actual size or 100% scale. Turn off browser headers and footers."),
  ], "Open print dialog", () => {
    printMode = mode;
    renderPrint(mode);
    window.print();
  });
}

function renderLabels() {
  const sheets = [];
  for (let start = 0; start < works.length; start += 8) {
    const sheet = node("section", "label-sheet");
    for (const work of works.slice(start, start + 8)) {
      const slot = node("div", "print-slot");
      slot.append(labelFor(work));
      for (const corner of ["tl", "tr", "bl", "br"]) {
        slot.append(node("span", "trim-mark trim-" + corner));
      }
      sheet.append(slot);
    }
    sheets.push(sheet);
  }
  return sheets;
}

function renderChecklist() {
  const checklist = node("section", "checklist");
  const header = node("header");
  header.append(node("h1", "", "Installation checklist"), node("p", "", "Hanging order · " + works.length + (works.length === 1 ? " work" : " works")));
  const list = node("ol");
  works.forEach((work, index) => {
    const item = node("li");
    const title = node("h2");
    const box = node("span", "check-box");
    box.setAttribute("aria-hidden", "true");
    const number = node("span", "check-number", String(index + 1).padStart(2, "0"));
    number.setAttribute("aria-hidden", "true");
    title.append(box, number, node("span", "", titleOf(work)));
    item.append(title);
    for (const line of [work.artist, metadata(work), work.dimensions]) {
      if (line.trim()) item.append(node("p", "", line));
    }
    if (work.credit.trim()) item.append(node("p", "check-credit", work.credit));
    list.append(item);
  });
  checklist.append(header, list);
  return checklist;
}

function renderPrint(mode) {
  if (mode === "checklist" && works.length) {
    printOutput.replaceChildren(renderChecklist());
    return;
  }
  if (works.length && labelIssues().length === 0) {
    printOutput.replaceChildren(...renderLabels());
    return;
  }
  const notice = node("section", "print-notice");
  notice.append(node("h1", "", "Labels need review"), node("p", "", works.length
    ? "Return to the workbench and choose Print labels to review text overflow and missing details."
    : "Add an artwork in the workbench to prepare labels."));
  printOutput.replaceChildren(notice);
}

artworkForm.addEventListener("submit", (event) => event.preventDefault());
artworkForm.addEventListener("input", (event) => {
  const work = works[positionOf()];
  const field = event.target.name;
  if (!work || !fields.includes(field)) return;
  work[field] = event.target.value;
  saveWorkspace();
  updatePreview(work);
  updateListEntry(workList.children[positionOf()].firstElementChild, work);
});
workList.addEventListener("click", (event) => {
  const button = event.target.closest(".work-button");
  if (!button) return;
  selectWork(button.dataset.id);
  workList.children[positionOf()].firstElementChild.focus();
});
byId("move-up").addEventListener("click", () => moveWork(-1));
byId("move-down").addEventListener("click", () => moveWork(1));
function stepPreview(offset) {
  const id = works[positionOf() + offset]?.id;
  selectWork(id);
  const direction = byId(offset < 0 ? "previous-work" : "next-work");
  if (direction.disabled) byId(offset < 0 ? "next-work" : "previous-work").focus();
}
byId("previous-work").addEventListener("click", () => stepPreview(-1));
byId("next-work").addEventListener("click", () => stepPreview(1));
byId("add-work").addEventListener("click", addWork);
byId("remove-work").addEventListener("click", removeWork);
byId("print-labels").addEventListener("click", () => confirmPrint("labels"));
byId("print-checklist").addEventListener("click", () => confirmPrint("checklist"));
byId("close-dialog").addEventListener("click", () => dialog.close());
dialog.addEventListener("close", () => {
  const action = dialogAction;
  dialogAction = undefined;
  if (dialog.returnValue === "confirm") action?.();
});
window.addEventListener("beforeprint", () => renderPrint(printMode || "labels"));
window.addEventListener("afterprint", () => {
  printMode = undefined;
  printOutput.replaceChildren();
});
new ResizeObserver(layoutProof).observe(proofStage);

for (const work of works) checkLabel(work, labelFor(work));
renderWorkspace();
if (loadError) {
  const status = byId("save-status");
  status.textContent = "Saved workspace unavailable. Showing sample works.";
  status.parentElement.classList.add("unsaved");
}
